-- Straight-line "map distance" between two systems, same abstract units
-- as map_x/map_y.
function M.distance(id_a, id_b)
	local a, b = M.SYSTEMS[id_a], M.SYSTEMS[id_b]
	if not a or not b then
		return nil
	end
	local dx, dy = a.map_x - b.map_x, a.map_y - b.map_y
	return math.sqrt(dx * dx + dy * dy)
end

-- Conversion factor between main/data/ships.lua's light-year stats
-- (ftl_range_ly, ftl_cost_hydrogen_per_ly) and this file's map_x/map_y
-- units. Set from one known distance, per direct instruction: 74 Imsida ->
-- 14 Toah (our 70 Virginis -> Deneb) is 8.25 light-years, i.e. 197.0 map
-- units / 8.25 = 23.877 units per light-year. That agrees with the original
-- game's own scale (the BSGO server emulator stores FTL range as light-years
-- x 20 in its own map units, about 1.19 screenshot pixels each), so the
-- ships' real light-year stats stay as they are. Callers comparing a ship's
-- FTL range against M.distance()'s output should convert through
-- M.ly_to_map_units() first - M.distance()/M.in_ftl_range() themselves stay
-- in plain map units.
M.SCALE_REFERENCE = { from = "70_virginis", to = "deneb", ly = 8.25 }
M.MAP_UNITS_PER_LY = M.distance(M.SCALE_REFERENCE.from, M.SCALE_REFERENCE.to) / M.SCALE_REFERENCE.ly

function M.ly_to_map_units(ly)
	return ly * M.MAP_UNITS_PER_LY
end

function M.map_units_to_ly(units)
	return units / M.MAP_UNITS_PER_LY
end

-- Which faction (if any) this system is restricted to for entry purposes -
-- either it's that faction's home system, or one of the 3 systems in that
-- faction's home buffer zone (M.HOME_BUFFER above). Returns nil if the
-- system is open to both.
function M.zone_owner(system_id)
	local home = M.faction_home_of(system_id)
	if home then
		return home
	end
	for faction, buffer in pairs(M.HOME_BUFFER) do
		for _, id in ipairs(buffer) do
			if id == system_id then
				return faction
			end
		end
	end
	return nil
end

-- Can `faction` ("accord"/"swarm") ever jump into `system_id` at all?
-- Blocked if the system belongs to the OTHER faction's home system or
-- home buffer zone (M.zone_owner) - everything else is open to both.
function M.can_enter(system_id, faction)
	if not M.SYSTEMS[system_id] then
		return false
	end
	local owner = M.zone_owner(system_id)
	return owner == nil or owner == faction
end

-- Is `distance` (may be nil) within `range`?
function M.in_ftl_range(distance, range)
	if distance == nil then
		return false
	end
	return distance <= range
end

-- Every system reachable from `from_id` with `ftl_range` (map units, same
-- scale as ship_classes.lua's FTL Range stat), for `faction`, sorted
-- nearest-first. `from_id` itself is excluded.
function M.reachable_from(from_id, ftl_range, faction)
	local out = {}
	for id, _ in pairs(M.SYSTEMS) do
		if id ~= from_id and M.can_enter(id, faction) then
			local d = M.distance(from_id, id)
			if d and d <= ftl_range then
				table.insert(out, { id = id, distance = d })
			end
		end
	end
	table.sort(out, function(a, b) return a.distance < b.distance end)
	return out
end

-- Hydrogen cost of a jump, as in the original game: distance in
-- light-years x the ship's FTL Cost (main/data/ships.lua's
-- ftl_cost_hydrogen_per_ly - the wiki's "Tyl/LY"). Rounded up so a jump
-- never costs less than the rate says. `distance` is in map units.
-- TEMPORARY: FTL jumps are free while this is true (range limits still
-- apply). Delete this line to charge Hydrogen again.
M.FREE_JUMPS = true

function M.hydrogen_cost(distance, cost_per_ly)
	if M.FREE_JUMPS then
		return 0
	end
	return math.ceil(M.map_units_to_ly(distance) * cost_per_ly - 1e-9)
end

return M
